using System.Diagnostics;using System.Windows;using System.Windows.Input;namespace RB22.GameBooster;public partial class OverlayWindow:Window{public OverlayWindow(){InitializeComponent();MouseLeftButtonDown+=(s,e)=>DragMove();var t=new System.Windows.Threading.DispatcherTimer{Interval=System.TimeSpan.FromSeconds(1)};t.Tick+=(s,e)=>{try{using var p=new PerformanceCounter("Processor","% Processor Time","_Total");p.NextValue();System.Threading.Thread.Sleep(30);Cpu.Text=$"{p.NextValue():F0}%";}catch{Cpu.Text="N/A";}try{using var p=new PerformanceCounter("Memory","% Committed Bytes In Use");Ram.Text=$"{p.NextValue():F0}%";}catch{Ram.Text="N/A";}Ping.Text="—";};t.Start();}void Close_Click(object s,RoutedEventArgs e)=>Close();}